import csv
import io
import re
from collections import Counter


def parse_csv(raw_csv: str):
    if not raw_csv:
        return {"columns": [], "rows": []}

    known_header_names = {
        "id", "title", "author", "authors", "abstract", "doi", "keyword",
        "keywords", "kw", "name", "date", "year", "type", "url", "email",
        "description", "category", "subject", "status", "value", "count",
        "qry-heter", "qry-n", "qry-ieee-1", "qry-ieee-2", "qry-ieee-3",
    }

    def normalized(value):
        return re.sub(r"\s+", " ", value.strip().lower())

    def header_score(record):
        cells = [normalized(value) for value in record]
        nonempty = [value for value in cells if value]
        if len(nonempty) < 2:
            return 0

        recognized = sum(value in known_header_names for value in nonempty)
        short = sum(len(value) <= 40 for value in nonempty)
        unique = len(set(nonempty))
        score = recognized * 4 + short / len(nonempty) + unique / len(nonempty)

        # Prefer rows that look like field names rather than prose.
        if len(nonempty) >= 2 and recognized >= 2:
            score += 3
        return score

    def read_with_delimiter(delimiter):
        stream = io.StringIO(raw_csv, newline="")
        try:
            return list(csv.reader(
                stream,
                delimiter=delimiter,
                quotechar='"',
                doublequote=True,
                strict=False,
            ))
        except csv.Error:
            return []

    candidates = []
    for delimiter in (",", ";", "\t", "|"):
        records = read_with_delimiter(delimiter)
        nonblank = [record for record in records if any(value.strip() for value in record)]
        if not nonblank:
            continue

        best_header_score = max((header_score(record) for record in nonblank), default=0)
        widths = Counter(len(record) for record in nonblank)
        modal_width, modal_count = widths.most_common(1)[0]
        consistency = modal_count / len(nonblank)
        candidates.append((
            best_header_score,
            modal_width,
            consistency,
            delimiter,
            records,
        ))

    if not candidates:
        return {"columns": [], "rows": []}

    # Header evidence takes priority; width and consistency break ties.
    _, _, _, _, records = max(candidates, key=lambda item: item[:3])

    nonblank_indices = [
        index for index, record in enumerate(records)
        if any(value.strip() for value in record)
    ]
    if not nonblank_indices:
        return {"columns": [], "rows": []}

    header_index = max(
        nonblank_indices,
        key=lambda index: (header_score(records[index]), -index),
    )

    # If no convincing header is present, use the first nonblank record.
    if header_score(records[header_index]) < 2:
        header_index = nonblank_indices[0]

    columns = [value.strip() for value in records[header_index]]
    if not columns:
        columns = ["Column_1"]

    rows = [
        record[:]
        for record in records[header_index + 1:]
        if record and any(value.strip() for value in record)
    ]

    width = max([len(columns)] + [len(row) for row in rows])
    while len(columns) < width:
        columns.append("Column_" + str(len(columns) + 1))

    for row in rows:
        if len(row) < width:
            row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
